using System;using System.Collections.Generic;using System.Globalization;using System.Linq;using LibreHardwareMonitor.Hardware;
namespace JonsboStudio {
 static class SensorBindings {
  static readonly Dictionary<string,string> aliases=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase){{"MemoryUseInt","MemoryUsage"},{"MemoryUsageSize","UsedMemory"},{"MemorySize","TotalMemory"},{"MemoryCanUsageSize","AvailableMemory"},{"MemoryCanUsage","AvailableMemoryUsage"},{"RAMUsage","MemoryUsage"},{"CPUT","CPUTemp"},{"GPUT","GPUTemp"}};
  public static string Canonical(string binding){string value;return aliases.TryGetValue(binding??"",out value)?value:binding??"";}
  public static void ApplyAliases(Dictionary<string,string> values){foreach(var alias in aliases){string value;if(values.TryGetValue(alias.Value,out value))values[alias.Key]=value;}string used,total;if(values.TryGetValue("UsedMemory",out used)&&values.TryGetValue("TotalMemory",out total))values["MemoryUse"]=used+" | "+total;}
 }
 sealed class SensorReading {public string name;public SensorType type;public double value;public SensorReading(string name,SensorType type,double value){this.name=name;this.type=type;this.value=value;}}
 static class SensorMapping {
  public static List<SensorReading> Read(IHardware hardware){var readings=new List<SensorReading>();Read(hardware,readings);return readings;}
  static void Read(IHardware hardware,List<SensorReading> readings){hardware.Update();foreach(var sensor in hardware.Sensors)if(sensor.Value.HasValue&&!float.IsNaN(sensor.Value.Value)&&!float.IsInfinity(sensor.Value.Value))readings.Add(new SensorReading(sensor.Name,sensor.SensorType,sensor.Value.Value));foreach(var child in hardware.SubHardware)Read(child,readings);}
  static bool Has(string name,string text){return name.IndexOf(text,StringComparison.OrdinalIgnoreCase)>=0;}
  static SensorReading Best(IEnumerable<SensorReading> readings,SensorType type,Func<string,int> rank){return readings.Where(s=>s.type==type&&rank(s.name)<100).OrderBy(s=>rank(s.name)).FirstOrDefault();}
  static void Put(Dictionary<string,string> values,string key,SensorReading reading,string format){if(reading!=null)values[key]=reading.value.ToString(format,CultureInfo.InvariantCulture);}
  public static Dictionary<string,string> Cpu(IEnumerable<SensorReading> readings){var all=readings.ToList();var values=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);var temperatures=all.Where(s=>s.type==SensorType.Temperature&&s.value>0&&s.value<=150).ToList();var temperature=Best(temperatures,SensorType.Temperature,n=>Has(n,"CPU Package")?0:Has(n,"Tdie")&&!Has(n,"Tctl")?1:Has(n,"Tctl/Tdie")?2:Has(n,"Tctl")?3:100);if(temperature==null)temperature=temperatures.Where(s=>Has(s.name,"Core")||Has(s.name,"CPU")).OrderByDescending(s=>s.value).FirstOrDefault();Put(values,"CPUTemp",temperature,"0");Put(values,"CpuTEC",Best(all.Where(s=>s.value>0),SensorType.Power,n=>Has(n,"CPU Package")?0:n.Equals("Package",StringComparison.OrdinalIgnoreCase)?1:Has(n,"PPT")?2:100),"0");var clocks=all.Where(s=>s.type==SensorType.Clock&&s.value>0&&Has(s.name,"Core")&&!Has(s.name,"Effective")).ToList();if(clocks.Count>0)values["CpuFrequency"]=clocks.Average(s=>s.value).ToString("0",CultureInfo.InvariantCulture);else Put(values,"CpuFrequency",Best(all,SensorType.Clock,n=>Has(n,"CPU")&&!Has(n,"Bus")?0:100),"0");Put(values,"CpuVoltage",Best(all.Where(s=>s.value>0),SensorType.Voltage,n=>Has(n,"Vcore")?0:Has(n,"CPU Core")&&!Has(n,"VID")?1:100),"0.00");return values;}
  public static Dictionary<string,string> Gpu(IEnumerable<SensorReading> readings){var all=readings.ToList();var values=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);Put(values,"GPUTemp",Best(all.Where(s=>s.value>0&&s.value<=150),SensorType.Temperature,n=>Has(n,"Core")&&!Has(n,"Hot")?0:n.Equals("GPU",StringComparison.OrdinalIgnoreCase)?1:100),"0");Put(values,"GpuUsage",Best(all,SensorType.Load,n=>Has(n,"Core")?0:Has(n,"D3D 3D")?1:100),"0");Put(values,"GpuFrequency",Best(all,SensorType.Clock,n=>Has(n,"Core")?0:100),"0");Put(values,"GpuVoltage",Best(all,SensorType.Voltage,n=>Has(n,"Core")?0:100),"0.00");Put(values,"GpuTEC",Best(all,SensorType.Power,n=>Has(n,"Total")?0:Has(n,"Package")?1:Has(n,"GPU Power")?2:Has(n,"Core")?3:100),"0");return values;}
  public static void Merge(Dictionary<string,string> target,Dictionary<string,string> values){foreach(var item in values)if(!target.ContainsKey(item.Key))target[item.Key]=item.Value;}
 }
}
